for r, (cit, tar_ar, full_ar, tar_bn, full_bn) in ism_fixes.items():
    ws.cell(r, 10).value = cit
    ws.cell(r, 11).value = tar_ar
    ws.cell(r, 12).value = full_ar
    ws.cell(r, 13).value = tar_bn
    ws.cell(r, 14).value = full_bn

# 2. Fix all 28 rows pointing to ذَٰلِكَ in 2:2
for r in range(2, ws.max_row + 1):
    if ws.cell(r, 11).value == 'ذَٰلِكَ':
        ws.cell(r, 11).value = 'ٱلْكِتَـٰبُ'
        ws.cell(r, 12).value = 'ذَٰلِكَ ([ٱلْكِتَـٰبُ]) لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ'
        ws.cell(r, 13).value = 'কিতাব'
        ws.cell(r, 14).value = 'এটা সেই ([কিতাব]) যাতে কোনো সন্দেহ নেই, মুত্তাকীদের জন্য হেদায়াত।'

# 3. Harmonize Col 9 = Col 13 for all 3091 rows
for r in range(2, ws.max_row + 1):
    c13 = str(ws.cell(r, 13).value or '').strip()
    ws.cell(r, 9).value = c13

wb.save('db/qw_bn.xlsx')
print('Ism sheet successfully curated and saved to db/qw_bn.xlsx!')
